import React from 'react';
import styled from '@emotion/styled';
import {
  Card,
  CardActions,
  CardContent,
  Box,
  Typography,
  Stack,
} from '@mui/material';

import { IconButton } from 'gatsby-theme-material-ui';
import { IosShare, RemoveRedEyeOutlined } from '@mui/icons-material';
import { ItemMap__Props, Item__Props } from './ItemMap';
import { navigate } from 'gatsby';
import slugify from 'slugify';
import moment from 'moment';
import { SingleProjectResponse } from '../../hooks/useAllProjects';
import { MusicItem } from '../../hooks/useAllMusic';
import { SkillItem } from '../../hooks/useAllSkills';
const StyledItem = styled(Card)`
  width: 350px;
  box-shadow: 0px 0px 16px -5px black;
`;

const StyledSkillChip = styled(Box)`
  &.skill-creative {
    background-color: var(--creative);
  }
  &.skill-backend {
    background-color: var(--backend);
  }
  &.skill-frontend {
    background-color: var(--frontend);
  }
  &.skill-other {
    background-color: var(--other);
  }
`;

type SingleItem__Props = Item__Props & {
  thumbnailComponent: React.ReactNode;
  onCopyLink: () => void;
  skills: SkillItem[];
};

export const getItemFromProjects = (
  projects: SingleProjectResponse[],
): Partial<ItemMap__Props[]> => {
  return projects.map((p) => ({
    data: {
      id: p.id,
      date: p.Completed,
      category: 'project',
      title: p.Title,
      detailLink: `/projects/${slugify(p.Title, { lower: true })}`,
      embedLink: p.LiveLink,
      tags: p.tags.flatMap((t) => t.tagName.toLowerCase()),
      snippet: p?.Narrative?.data?.childMarkdownRemark?.excerpt || '',
      readTime: p?.Narrative?.data?.childMarkdownRemark?.timeToRead || null,
      image: { url: p.Cover?.url || null },
      type: 'project',
      skillIds: p.skills.flatMap((s) => s.skill.strapi_id),
      // image: i.Gallery.data[0].attributes.?url,
    },
  }));
};

export const getItemFromMusics = (musics: MusicItem[]): ItemMap__Props[] => {
  return musics.map(({ id, attributes: i }) => ({
    data: {
      id: id,
      date: i.released,
      category: 'music',
      title: i.Title,
      embedLink: i.embedLink,
      detailLink: `/sounds/${slugify(i.Title, { lower: true })}`,
      tags: i.tags.data.flatMap((d) => d.attributes.tagName.toLowerCase()),
      snippet: i.Narrative,
      image: { url: i.artwork?.data[0]?.attributes?.url || null },
      type: i.platform,
      skillIds: [],
    },
  }));
};

const SingleItem = ({
  title,
  snippet,
  tags,
  thumbnailComponent,
  category,
  detailLink,
  id,
  readTime,
  date,
  onCopyLink,
  skills,
}: SingleItem__Props) => (
  <StyledItem elevation={0}>
    <Box onClick={() => navigate(detailLink)} sx={{ cursor: 'pointer' }}>
      {thumbnailComponent}
    </Box>

    <CardContent>
      <Box onClick={() => navigate(detailLink)} style={{ cursor: 'pointer' }}>
        <Typography variant="h5" component="div">
          {title}
        </Typography>

        <Typography
          variant="caption"
          sx={{ color: 'primary.light', fontWeight: 400 }}
        >
          {moment(date).fromNow().toString()}
        </Typography>
        <Box sx={{ pt: 2 }}>
          <Typography variant="body2" color="text.secondary">
            {snippet}
          </Typography>
        </Box>
      </Box>
    </CardContent>
    <Stack
      gap={0.25}
      flexDirection={'row'}
      flexWrap={'wrap'}
      sx={{ pb: 2, px: 2 }}
    >
      {/* {tags.map((t) => (
            <Chip key={t} color="primary" label={t} />
          ))} */}
      {skills &&
        skills.map((skill) => (
          <>
            {/* <img
                style={{
                  width: '24px',
                  height: '24px',
                  marginRight: '8px',
                  borderRadius: '100px',
                }}
                src={skill.attributes.skill.Icon.data.attributes.url}
                alt={skill.attributes.skill.SkillName}
              /> */}
            <StyledSkillChip
              key={skill.id}
              className={`skill-${skill.attributes.SkillCategory}`}
              sx={{
                mr: 1,
                mb: '8px',
                px: 1,
                py: 0.5,
                borderRadius: '20px',
                fontSize: '0.75rem',
                fontWeight: 800,
                color: 'white',
              }}
            >
              {skill.attributes.skill.SkillName}
            </StyledSkillChip>
          </>
        ))}
    </Stack>
    <CardActions>
      {readTime && (
        <Box sx={{ p: 2 }}>
          <Typography
            variant="caption"
            sx={{ color: 'white', fontWeight: 400 }}
          >
            {readTime?.toString()} Minute Read
          </Typography>
          <Box></Box>
        </Box>
      )}
      <Box sx={{ flexGrow: '1' }} />

      <IconButton
        onClick={() => onCopyLink('https://albertsigman.com' + detailLink)}
      >
        <IosShare />
      </IconButton>
      <IconButton>
        <RemoveRedEyeOutlined />
      </IconButton>
    </CardActions>
  </StyledItem>
);

export default SingleItem;
